param()
$ErrorActionPreference='Stop';[Console]::InputEncoding=[Text.Encoding]::UTF8;[Console]::OutputEncoding=[Text.Encoding]::UTF8
$p=$null;$db=$null;$tx=$null
try{
 $p=[Console]::In.ReadToEnd()|ConvertFrom-Json;if($p.scope -cne 'SCCRM-RECEIPT-TIME-OPERATOR-V1'){throw 'RECEIPT_TIME_SCOPE_REFUSED'}
 $b=New-Object Data.SqlClient.SqlConnectionStringBuilder;$b['Data Source']=$p.target.server;$b['Initial Catalog']=$p.target.database;$b['User ID']=$p.credentials.user;$b['Password']=$p.credentials.password;$b['Connect Timeout']=5;$b['Pooling']=$false;$b['Application Name']='SCCRM-Receipt-Time-Operator'
 $db=New-Object Data.SqlClient.SqlConnection $b.ConnectionString;$db.Open();$b['Password']='';$p.credentials.password=''
 $q=$db.CreateCommand();$q.CommandTimeout=5;$q.CommandText='SET LOCK_TIMEOUT 1000;SET DEADLOCK_PRIORITY LOW;SET ANSI_NULLS ON;SET ANSI_PADDING ON;SET ANSI_WARNINGS ON;SET ARITHABORT ON;SET CONCAT_NULL_YIELDS_NULL ON;SET QUOTED_IDENTIFIER ON;SET NUMERIC_ROUNDABORT OFF;SELECT CONVERT(varchar(128),SERVERPROPERTY(''MachineName'')),DB_NAME()';$r=$q.ExecuteReader();if(!$r.Read() -or $r.GetString(0) -cne $p.target.machine -or $r.GetString(1) -cne $p.target.database){throw 'RECEIPT_TIME_TARGET_REFUSED'};$r.Dispose();$q.Dispose()
 if($p.copy){if($p.target.machine -cne 'SERVER' -or $p.target.database -cnotmatch '^SCCRM_ReceiptTimeCopy_20261111_00[01345]$'){throw 'RECEIPT_TIME_COPY_ONLY'};$q=$db.CreateCommand();$q.CommandText="IF NOT EXISTS(SELECT 1 FROM dbo.SCCRM_TimeCopyOwner WHERE marker='4afc7446-846e-4d6a-8a1b-e672655b1a38') RAISERROR('RECEIPT_TIME_COPY_OWNER_REFUSED',16,1);";$null=$q.ExecuteNonQuery();$q.Dispose()}
 if($p.receiptWorker){if(!$p.copy){throw 'RECEIPT_TIME_COPY_ONLY'};$q=$db.CreateCommand();$q.CommandText="EXECUTE AS USER='SCCRM_ReceiptCopyWorker' WITH NO REVERT;";$null=$q.ExecuteNonQuery();$q.Dispose()}
 if($p.transaction){$tx=$db.BeginTransaction()}
 $results=@();foreach($sql in @($p.statements)){$q=$db.CreateCommand();$q.CommandTimeout=30;$q.CommandText=[string]$sql;if($tx){$q.Transaction=$tx}
  if($p.parameters){foreach($property in $p.parameters.PSObject.Properties){if($property.Name -cnotmatch '^[A-Za-z][A-Za-z0-9_]*$'){throw 'RECEIPT_TIME_PARAMETER_REFUSED'};$v=$property.Value;$type=if($v -is [double] -or $v -is [decimal]){[Data.SqlDbType]::Float}elseif($v -is [int] -or $v -is [long]){[Data.SqlDbType]::BigInt}else{[Data.SqlDbType]::NVarChar};$param=$q.Parameters.Add('@'+$property.Name,$type);if($type -eq [Data.SqlDbType]::NVarChar){$param.Size=-1};$param.Value=if($null -eq $v){[DBNull]::Value}else{$v}}}
  foreach($dateName in @($p.dateParameters)){if($dateName -and $q.Parameters.Contains('@'+$dateName)){$param=$q.Parameters['@'+$dateName];if($param.Value -isnot [DBNull]){$param.Value=[DateTime]::Parse([string]$param.Value,[Globalization.CultureInfo]::InvariantCulture)};$param.SqlDbType=[Data.SqlDbType]::DateTime}}
  $r=$null;try{$r=$q.ExecuteReader();do{$rows=@();while($r.Read()){$row=[ordered]@{};for($i=0;$i -lt $r.FieldCount;$i++){$v=$r.GetValue($i);if($v -is [DBNull]){$v=$null}elseif($v -is [DateTime]){$v=$v.ToString('o',[Globalization.CultureInfo]::InvariantCulture)};$row[$r.GetName($i)]=$v};$rows+=[pscustomobject]$row};if($r.FieldCount -gt 0){$results+=,@($rows)}}while($r.NextResult())}finally{if($r){$r.Dispose()};$q.Dispose()}}
 if($tx){$tx.Commit();$tx.Dispose();$tx=$null}
 @{ok=$true;results=$results;copyOnly=[bool]$p.copy}|ConvertTo-Json -Depth 25 -Compress
}catch{if($tx){try{$tx.Rollback()}catch{}};$e=$_.Exception.GetBaseException();@{ok=$false;code=$(if($e.Message -cmatch '^RECEIPT_[A-Z_]+$'){$e.Message}else{'RECEIPT_TIME_SQL_FAILED'});sqlNumber=$(if($e -is [Data.SqlClient.SqlException]){$e.Number}else{$null});detail=$(if($p.copy){$e.Message}else{'withheld'})}|ConvertTo-Json -Compress;exit 1}finally{if($tx){$tx.Dispose()};if($db){$db.Dispose()};if($p){$p.credentials.password=''}}
